contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a scenario: set MinSum, initialize log, put some funds, then try Collect;
    // ensure that when Collect succeeds, both the contract's recorded balance for
    // this contract and the contract's ETH balance drop by exactly the collected amount.
    function run(uint minSum, uint lockTime, uint putAmount, uint collectAmount, address logAddr) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance");
        // set up MinSum and LogFile before initialization
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        // mark initialized so further setup can't be changed
        c.Initialized();

        // read before-values
        (uint beforeHolderUnlock, uint beforeHolderBalance) = c.Acc(address(this));
        uint beforeContractEth = address(c).balance;

        // perform Put to deposit putAmount into c under this contract's holder
        c.Put{value: putAmount}(lockTime);

        // read after put
        (uint midUnlock, uint midHolderBalance) = c.Acc(address(this));
        uint midContractEth = address(c).balance;

        // sanity: holder balance increased by putAmount and contract balance increased
        // (these are not in assert final; they help ensure Collect path meaningful)
        // Now attempt Collect and catch whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final state
        (uint finalUnlock, uint finalHolderBalance) = c.Acc(address(this));
        uint finalContractEth = address(c).balance;

        // If Collect succeeded (did not revert), then holder balance decreased by exactly collectAmount
        // and contract ETH balance decreased by exactly collectAmount. Otherwise nothing required.
        assert(collectReverted || (midHolderBalance >= collectAmount && midHolderBalance - finalHolderBalance == collectAmount && midContractEth >= collectAmount && midContractEth - finalContractEth == collectAmount));
    }

    receive() external payable {}
}

