contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: try to Collect and check that if the call succeeded,
    // then the recorded holder balance after the call is either >= MinSum or was unchanged (i.e., collect didn't illegally reduce it below MinSum).
    // We take collectAmount as input and must have some Ether to forward if needed (Collect is payable but sends out Ether).
    function run(uint collectAmount) public payable {
        require(true);

        // Read MinSum and holder balance before the attempt
        uint minBefore = c.MinSum();
        (, uint balBefore) = c.Acc(address(this));
        uint contractBalBefore = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder balance after attempt
        (, uint balAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // If Collect succeeded then the following must hold:
        // - balAfter = balBefore - collectAmount  OR Collect did nothing (call path guards may prevent change)
        //   however to be conservative and general: if call succeeded, balAfter <= balBefore.
        // - also, Collect is only allowed when balBefore >= MinSum and balBefore >= collectAmount and block.timestamp>unlockTime.
        //   We can't read unlockTime directly here (it is public via Acc), but we did read Acc. Ensure that if Collect succeeded then balAfter <= balBefore and contract balance decreased by at most collectAmount.
        assert(reverted || (balAfter <= balBefore && contractBalAfter + collectAmount == contractBalBefore && balBefore >= minBefore && balBefore >= collectAmount));
    }

    // Allow this test contract to receive Ether
    receive() external payable {}
}

