        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Put and capture whether it reverted
        bool reverted;
        try c.Put{value: putAmount}(putLockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Assert the general invariant: on success both stored balance and contract balance increase by putAmount and unlockTime does not decrease;
        // on revert none of those observables change.
        assert(
            reverted
            ? (afterBal == beforeBal && afterContractBal == beforeContractBal && afterUnlock == beforeUnlock)
            : (afterBal == beforeBal + putAmount && afterContractBal == beforeContractBal + putAmount && afterUnlock >= beforeUnlock)
        );
    }

    // receive to accept ETH forwarded by C.Log (defensive)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We attempt to Put some funds, then (possibly) Collect an amount; if Collect succeeds it must transfer ETH to this contract
    function run(uint putLock, uint putAmount, uint collectAmount, uint initMinSum) public payable {
        // ensure this test contract has ETH to fund the Put
        require(address(this).balance >= putAmount);

        // initialize c so MinSum and LogFile are set before making Put/Collect and then mark initialized
        c.SetMinSum(initMinSum);
        c.SetLogFile(address(this));
        c.Initialized();

        // record before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // Do Put (may revert). We capture revert but continue.
        bool putReverted;
        try c.Put{value: putAmount}(putLock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put, attempt Collect of collectAmount and capture whether it reverted.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // If Collect succeeded then:
        // - c's recorded balance for this contract must have decreased by at least collectAmount (it cannot underflow, so decrease >= collectAmount)
        // - address(c).balance must have decreased by exactly the amount that increased this contract's balance
        // We assert that when collectReverted == false these relations hold. When collectReverted == true we don't constrain.
        assert(collectReverted || (
            // observed outgoing from c equals incoming to this test contract
            (beforeContractBal >= afterContractBal) && (afterThisBal >= beforeThisBal) && ((beforeContractBal - afterContractBal) == (afterThisBal - beforeThisBal))
            // and the stored recorded balance decreased by at least the transferred amount
            && (beforeBal >= afterBal) && ((beforeBal - afterBal) >= (afterThisBal - beforeThisBal))
        ));
    }

    // receive to accept ETH sent by c during Collect or Log
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put on c with a sender equal to this test contract.
    // Params:
    //  - uint lockTime: passed to Put
    //  - uint amount: ether to send with Put (must be available in this contract)
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read observed before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        // Perform the call and capture whether it reverted
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // General property:
        // If Put succeeded then the recorded per-address balance increases by exactly amount
        // and the contract's ether balance does not decrease (in practice should increase by >= amount).
        // If Put reverted then neither per-address balance nor contract balance change.
        assert(
            reverted
            ? (afterBalance == beforeBalance && afterContractBalance == beforeContractBalance)
            : (afterBalance == beforeBalance + amount && afterContractBalance >= beforeContractBalance)
        );
    }

    receive() external payable {}
}
